                ItemStack input = inventory.getStackInSlot(i);
                if (ItemUtil.areItemsEqual(this.nbtCopyStack, input, true)) {
                    stack.setTagCompound(input.getTagCompound());
                    break;
                }
            }
        }
        return stack;
    }

